 13→/// A progress spinner for long-running operations.
 14→pub struct ProgressSpinner {
 15→    bar: ProgressBar,
 16→    indent: usize,
 17→}
 18→
 19→impl ProgressSpinner {
 20→    /// Create a new spinner with a message.
 21→    pub fn new(message: &str) -> Self {
 22→        Self::with_indent(message, 0)
 23→    }
 24→
 25→    /// Create a new spinner with indentation.
 26→    pub fn with_indent(message: &str, indent: usize) -> Self {
 27→        let bar = ProgressBar::new_spinner();
 28→        let prefix = " ".repeat(indent);
 29→        bar.set_style(
 30→            ProgressStyle::default_spinner()
 31→                .tick_chars("⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏")
 32→                .template(&format!("{}{{spinner:.magenta}} {{msg}}", prefix))
 33→                .unwrap(),
 34→        );
 35→        bar.set_message(message.to_string());
 36→        bar.enable_steady_tick(Duration::from_millis(80));
 37→
 38→        Self { bar, indent }
 39→    }
 40→
 41→    /// Create a spinner that doesn't show (for silent mode).
 42→    pub fn hidden() -> Self {
 43→        let bar = ProgressBar::hidden();
 44→        Self { bar, indent: 0 }
 45→    }
 46→
 47→    /// Get a clone of the inner progress bar for use in callbacks.
 48→    ///
 49→    /// This is useful for live output streaming: the cloned bar can be
 50→    /// passed to a callback running on another thread, and `set_message`
 51→    /// calls on it will update the spinner display in real-time.
 52→    pub fn bar_clone(&self) -> ProgressBar {
 53→        self.bar.clone()
 54→    }
 55→}
 56→
 57→impl SpinnerHandle for ProgressSpinner {
 58→    fn set_message(&mut self, msg: &str) {
 59→        self.bar.set_message(msg.to_string());
 60→    }
 61→
 62→    fn finish_success(&mut self, msg: &str) {
 63→        let prefix = " ".repeat(self.indent);
 64→        let theme = BivvyTheme::new();
 65→        self.bar
 66→            .set_style(ProgressStyle::default_spinner().template("{msg}").unwrap());
 67→        self.bar
 68→            .finish_with_message(format!("{}{}", prefix, theme.format_success(msg)));
 69→    }
 70→
 71→    fn finish_error(&mut self, msg: &str) {
 72→        let prefix = " ".repeat(self.indent);
 73→        let theme = BivvyTheme::new();
 74→        self.bar
 75→            .set_style(ProgressStyle::default_spinner().template("{msg}").unwrap());
 76→        self.bar
 77→            .finish_with_message(format!("{}{}", prefix, theme.format_error(msg)));
 78→    }
 79→
 80→    fn finish_skipped(&mut self, msg: &str) {
 81→        let prefix = " ".repeat(self.indent);
 82→        let theme = BivvyTheme::new();
 83→        self.bar
 84→            .set_style(ProgressStyle::default_spinner().template("{msg}").unwrap());
 85→        self.bar
 86→            .finish_with_message(format!("{}{}", prefix, theme.format_skipped(msg)));
 87→    }
 88→
 89→    fn progress_bar(&self) -> Option<ProgressBar> {
 90→        Some(self.bar.clone())
 91→    }
