 51→        let duration = self.start_time.elapsed();
 52→        let msg = format!(
 53→            "{} - {} ({})",
 54→            self.name,
 55→            self.description,
 56→            format_duration(duration)
 57→        );
 58→
 59→        if let Some(mut spinner) = self.spinner.take() {
 60→            spinner.finish_success(&msg);
 61→        } else {
 62→            println!("{}", self.theme.format_success(&msg));
 63→        }
 64→    }
