34→fn prompt_confirm(prompt: &Prompt, term: &Term) -> Result<PromptResult> {
35→    let default = prompt
36→        .default
37→        .as_ref()
38→        .map(|s| s.to_lowercase() == "true" || s == "y" || s == "yes")
39→        .unwrap_or(true);
40→
41→    let result = Confirm::new()
42→        .with_prompt(&prompt.question)
43→        .default(default)
44→        .interact_on(term)
45→        .map_err(map_dialoguer_err)?;
46→
47→    Ok(PromptResult::Bool(result))
48→}
