53→    let result: String = if let Some(default) = &prompt.default {
54→        input
55→            .default(default.clone())
56→            .interact_on(term)
57→            .map_err(map_dialoguer_err)?
58→    } else {
59→        input.interact_on(term).map_err(map_dialoguer_err)?
